class Solution {
    private long best = Long.MAX_VALUE;

    public int findInteger(int k, int digit1, int digit2) {
        dfs(0, k, new int[]{digit1, digit2});
        return best == Long.MAX_VALUE ? -1 : (int) best;
    }

    private void dfs(long cur, int k, int[] ds) {
        for (int d : ds) {
            long nxt = cur * 10 + d;
            if (nxt == 0 || nxt > Integer.MAX_VALUE) continue;
            if (nxt > k && nxt % k == 0) best = Math.min(best, nxt);
            dfs(nxt, k, ds);
        }
    }
}
